const TOPICS=[
{id:'mt',name:'Máy tính và thiết bị',sub:'Phần cứng, thiết bị vào ra, bộ nhớ',c:'#1766d1',icon:'<rect x="3" y="4" width="18" height="12" rx="2"/><path d="M9 20h6M12 16v4"/>',
 tip:'Gặp câu hỏi về thiết bị, em tự hỏi: thông tin đang đi <b>vào</b> máy hay đi <b>ra</b> khỏi máy?',
 L:[
 ['Phần cứng và phần mềm','<p><b>Phần cứng</b> là những thứ em sờ được: màn hình, bàn phím, chuột, thân máy.</p><p><b>Phần mềm</b> là các chương trình chạy bên trong máy như Word hay trò chơi. Em nhìn thấy nó trên màn hình nhưng không sờ được.</p><p>Giống như chiếc đàn là phần cứng, còn bản nhạc là phần mềm.</p>'],
 ['Thiết bị vào và thiết bị ra','<p><b>Thiết bị vào</b> đưa thông tin từ em vào máy: bàn phím, chuột, micro, máy quét, webcam.</p><p><b>Thiết bị ra</b> đưa thông tin từ máy đến em: màn hình, loa, tai nghe, máy in.</p><p>Màn hình cảm ứng làm được cả hai việc: em chạm để ra lệnh và nhìn để xem kết quả.</p>'],
 ['Bộ não và trí nhớ của máy','<ul><li><b>CPU</b> là bộ não, làm mọi phép tính.</li><li><b>RAM</b> là trí nhớ tạm. Tắt máy là RAM quên hết.</li><li><b>Ổ cứng, USB, thẻ nhớ</b> là trí nhớ lâu dài. Tắt máy dữ liệu vẫn còn.</li></ul><p>Vì vậy em phải <b>lưu bài</b> vào ổ cứng trước khi tắt máy.</p>'],
 ['Các loại máy tính','<p>Máy tính để bàn đặt cố định một chỗ. Máy tính xách tay (laptop) gập lại mang đi được. Máy tính bảng và điện thoại thông minh nhỏ gọn, dùng màn hình cảm ứng.</p>'],
 ['Đo dung lượng','<p>Dung lượng cho biết tệp to hay nhỏ, ổ đĩa chứa được nhiều hay ít. Từ bé đến lớn:</p><p><b>Byte → KB → MB → GB → TB</b></p><p>Mỗi bậc lớn hơn bậc trước khoảng 1000 lần. Một bức ảnh khoảng vài MB, một bộ phim khoảng vài GB.</p>'],
 ['Giữ máy luôn khoẻ','<ul><li>Tắt máy đúng cách: <b>Start → Power → Shut down</b>.</li><li>Không ăn uống cạnh máy, tay sạch và khô.</li><li>Không rút điện khi máy đang chạy.</li></ul>']
 ]},
{id:'hdh',name:'Hệ điều hành, tệp và thư mục',sub:'Windows, màn hình nền, sắp xếp tệp',c:'#0f8f8a',icon:'<path d="M3 7a2 2 0 0 1 2-2h4l2 2h8a2 2 0 0 1 2 2v8a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2z"/>',
 tip:'Nhìn <b>đuôi tệp</b> (phần sau dấu chấm) là biết tệp đó thuộc loại gì và mở bằng phần mềm nào.',
 L:[
 ['Hệ điều hành là gì?','<p>Hệ điều hành là <b>người quản lý</b> của máy tính. Nó điều khiển phần cứng và giúp các phần mềm khác chạy được.</p><p>Máy tính thường dùng <b>Windows, macOS, Linux</b>. Điện thoại và máy tính bảng dùng <b>Android, iOS</b>.</p>'],
 ['Màn hình nền Windows','<ul><li><b>Desktop</b> (màn hình nền) là nơi em thấy đầu tiên khi mở máy.</li><li><b>Icon</b> (biểu tượng) là hình nhỏ, bấm đúp để mở.</li><li><b>Taskbar</b> (thanh tác vụ) nằm dưới cùng, cho thấy các chương trình đang mở.</li><li><b>Nút Start</b> mở danh sách chương trình.</li><li><b>Recycle Bin</b> (Thùng rác) chứa tệp đã xoá.</li></ul>'],
 ['Tệp và thư mục','<p><b>Tệp</b> (file) giống một quyển vở: chứa bài văn, bức ảnh hay bài hát.</p><p><b>Thư mục</b> (folder) giống ngăn cặp: chứa nhiều tệp cho gọn. Trong thư mục có thể có <b>thư mục con</b>.</p><p>Đặt tên rõ ràng để dễ tìm, ví dụ <i>Bai-van-ta-me.docx</i>.</p>'],
 ['Đuôi tệp','<ul><li><b>.docx</b> văn bản Word, <b>.txt</b> văn bản thường, <b>.pdf</b> tài liệu để đọc</li><li><b>.xlsx</b> bảng tính Excel</li><li><b>.pptx</b> bài trình chiếu PowerPoint</li><li><b>.jpg, .png</b> hình ảnh</li><li><b>.mp3</b> âm thanh, <b>.mp4</b> video</li></ul>'],
 ['Làm việc với tệp','<ul><li><b>Rename</b>: đổi tên (phím <kbd>F2</kbd>).</li><li><b>Copy → Paste</b>: tạo thêm một bản giống hệt ở chỗ khác.</li><li><b>Cut → Paste</b>: chuyển tệp sang chỗ khác.</li><li><b>Delete</b>: xoá, tệp vào Thùng rác.</li><li><b>Restore</b>: lấy tệp từ Thùng rác về chỗ cũ.</li></ul>'],
 ['Ba nút của cửa sổ','<p>Ở góc trên bên phải mỗi cửa sổ có ba nút: <kbd>–</kbd> thu nhỏ xuống thanh tác vụ, <kbd>□</kbd> phóng to hết màn hình, <kbd>×</kbd> đóng cửa sổ.</p>']
 ]},
{id:'pm',name:'Phần mềm và thao tác chung',sub:'Chọn đúng phần mềm, lưu, phím tắt',c:'#7a4fd1',icon:'<rect x="4" y="4" width="7" height="7" rx="1.5"/><rect x="13" y="4" width="7" height="7" rx="1.5"/><rect x="4" y="13" width="7" height="7" rx="1.5"/><rect x="13" y="13" width="7" height="7" rx="1.5"/>',
 tip:'Các phím tắt <kbd>Ctrl</kbd>+<kbd>C</kbd>, <kbd>V</kbd>, <kbd>X</kbd>, <kbd>Z</kbd>, <kbd>S</kbd> dùng giống nhau ở hầu hết phần mềm. Thuộc một lần, dùng mọi nơi.',
 L:[
 ['Hai loại phần mềm','<p><b>Phần mềm hệ thống</b> giúp máy hoạt động, ví dụ hệ điều hành Windows.</p><p><b>Phần mềm ứng dụng</b> giúp em làm một việc cụ thể: Word, Excel, PowerPoint, Paint, trình duyệt Chrome.</p>'],
 ['Việc nào, phần mềm nấy','<ul><li>Viết thư, bài văn → <b>Word</b></li><li>Lập bảng, tính toán → <b>Excel</b></li><li>Thuyết trình trước lớp → <b>PowerPoint</b></li><li>Vẽ tranh → <b>Paint</b></li><li>Xem trang web → <b>trình duyệt</b> (Chrome, Edge)</li></ul>'],
 ['Save và Save As','<p><b>Save</b> (<kbd>Ctrl</kbd>+<kbd>S</kbd>) lưu thay đổi vào tệp đang mở.</p><p><b>Save As</b> lưu thành một tệp <b>mới</b> với tên khác hoặc ở chỗ khác. Tệp cũ vẫn giữ nguyên.</p>'],
 ['Các nút trên thanh công cụ','<p>Em hãy làm quen với hình các nút này. Trong bài thi em thường phải nhận ra chúng.</p>','word'],
 ['Phím tắt vàng','<ul><li><kbd>Ctrl</kbd>+<kbd>C</kbd> sao chép, <kbd>Ctrl</kbd>+<kbd>X</kbd> cắt, <kbd>Ctrl</kbd>+<kbd>V</kbd> dán</li><li><kbd>Ctrl</kbd>+<kbd>Z</kbd> hoàn tác (quay lại bước trước)</li><li><kbd>Ctrl</kbd>+<kbd>S</kbd> lưu, <kbd>Ctrl</kbd>+<kbd>P</kbd> in</li><li><kbd>Ctrl</kbd>+<kbd>A</kbd> chọn tất cả, <kbd>Ctrl</kbd>+<kbd>O</kbd> mở tệp, <kbd>Ctrl</kbd>+<kbd>N</kbd> tạo tệp mới</li></ul>'],
 ['Cài đặt và cập nhật','<p>Chỉ cài phần mềm từ nguồn tin cậy và hỏi người lớn trước. <b>Cập nhật</b> (update) giúp phần mềm sửa lỗi và an toàn hơn.</p><p>Khi phần mềm bị đứng: chờ một chút, đóng rồi mở lại, hoặc khởi động lại máy.</p>']
 ]},
{id:'vb',name:'Soạn thảo văn bản',sub:'Word: gõ, định dạng, chèn hình, in',c:'#2456b8',icon:'<path d="M6 3h9l4 4v14H6z"/><path d="M9 11h7M9 15h7"/>',
 tip:'Muốn đổi kiểu chữ nào thì phải <b>bôi đen</b> (chọn) chữ đó trước, rồi mới bấm nút định dạng.',
 L:[
 ['Gõ và sửa chữ','<ul><li><kbd>Enter</kbd> xuống dòng, bắt đầu đoạn mới.</li><li><kbd>Space</kbd> (phím cách) tạo khoảng trống giữa hai từ.</li><li><kbd>Backspace</kbd> xoá ký tự <b>bên trái</b> con trỏ.</li><li><kbd>Delete</kbd> xoá ký tự <b>bên phải</b> con trỏ.</li><li><kbd>Caps Lock</kbd> bật hoặc tắt chế độ gõ chữ in hoa.</li></ul>'],
 ['Định dạng chữ','<ul><li><b>B</b> (Bold) chữ đậm: <kbd>Ctrl</kbd>+<kbd>B</kbd></li><li><i>I</i> (Italic) chữ nghiêng: <kbd>Ctrl</kbd>+<kbd>I</kbd></li><li><u>U</u> (Underline) gạch chân: <kbd>Ctrl</kbd>+<kbd>U</kbd></li><li>Em còn đổi được phông chữ (Font), cỡ chữ (Size) và màu chữ.</li></ul>'],
 ['Căn lề đoạn văn','<ul><li>Căn trái: <kbd>Ctrl</kbd>+<kbd>L</kbd></li><li>Căn giữa: <kbd>Ctrl</kbd>+<kbd>E</kbd> (hay dùng cho tiêu đề)</li><li>Căn phải: <kbd>Ctrl</kbd>+<kbd>R</kbd></li><li>Căn đều hai bên: <kbd>Ctrl</kbd>+<kbd>J</kbd></li></ul>','word'],
 ['Chèn hình và bảng','<p>Mọi thứ muốn thêm vào trang đều nằm ở thẻ <b>Insert</b>: <b>Pictures</b> (hình ảnh), <b>Table</b> (bảng), <b>Shapes</b> (hình vẽ).</p>'],
 ['Kiểm tra chính tả và tìm kiếm','<p>Đường <b>gạch đỏ lượn sóng</b> dưới một từ nghĩa là từ đó có thể sai chính tả.</p><p><kbd>Ctrl</kbd>+<kbd>F</kbd> tìm một từ trong bài. <kbd>Ctrl</kbd>+<kbd>H</kbd> tìm và thay bằng từ khác.</p>'],
 ['In văn bản','<p>Nhấn <kbd>Ctrl</kbd>+<kbd>P</kbd> để in. Trước khi in em xem trước trang in để kiểm tra.</p><p>Giấy dọc gọi là <b>Portrait</b>, giấy ngang gọi là <b>Landscape</b>.</p>']
 ]},
{id:'bt',name:'Bảng tính',sub:'Excel: ô, công thức, hàm, biểu đồ',c:'#14885a',icon:'<rect x="3" y="4" width="18" height="16" rx="2"/><path d="M3 10h18M3 15h18M9 4v16M15 4v16"/>',
 tip:'Địa chỉ ô luôn đọc <b>cột trước, hàng sau</b>. Công thức luôn bắt đầu bằng dấu <kbd>=</kbd>.',
 L:[
 ['Hàng, cột và ô','<p><b>Cột</b> chạy dọc, đặt tên bằng chữ cái A, B, C. <b>Hàng</b> chạy ngang, đặt tên bằng số 1, 2, 3.</p><p><b>Ô</b> là nơi cột và hàng gặp nhau. Ô ở cột B, hàng 3 có địa chỉ là <b>B3</b>.</p>','excel'],
 ['Nhập dữ liệu','<p>Bấm vào ô rồi gõ chữ hoặc số. Nhấn <kbd>Enter</kbd> để xuống ô dưới, nhấn <kbd>Tab</kbd> để sang ô bên phải.</p>'],
 ['Công thức','<p>Công thức luôn bắt đầu bằng dấu <b>=</b>. Ví dụ <b>=A1+B1</b> cộng hai ô A1 và B1.</p><p>Dấu phép tính: cộng <kbd>+</kbd>, trừ <kbd>-</kbd>, nhân <kbd>*</kbd>, chia <kbd>/</kbd>. Excel cũng nhân chia trước, cộng trừ sau như trong môn Toán.</p>'],
 ['Các hàm hay gặp','<ul><li><b>=SUM(A1:A5)</b> tính tổng</li><li><b>=AVERAGE(A1:A5)</b> tính trung bình cộng</li><li><b>=MAX(A1:A5)</b> tìm số lớn nhất</li><li><b>=MIN(A1:A5)</b> tìm số nhỏ nhất</li><li><b>=COUNT(A1:A5)</b> đếm các ô có số</li></ul><p><b>A1:A5</b> nghĩa là các ô từ A1 đến A5, gồm 5 ô.</p>'],
 ['Sắp xếp và lọc','<p><b>Sort</b> sắp xếp dữ liệu, ví dụ tên theo thứ tự A đến Z hoặc điểm từ cao xuống thấp.</p><p><b>Filter</b> lọc, chỉ hiện những dòng em cần xem.</p>'],
 ['Biểu đồ','<ul><li><b>Biểu đồ cột</b>: so sánh các số với nhau.</li><li><b>Biểu đồ tròn</b>: mỗi phần chiếm bao nhiêu trong tổng thể.</li><li><b>Biểu đồ đường</b>: sự thay đổi theo thời gian.</li></ul>']
 ]},
{id:'tc',name:'Trình chiếu',sub:'PowerPoint: slide, hiệu ứng, thuyết trình',c:'#d9601a',icon:'<rect x="3" y="4" width="18" height="12" rx="1"/><path d="M10 8l4 2-4 2zM12 16v4M8 20h8"/>',
 tip:'<b>Transition</b> là hiệu ứng khi đổi <b>từ slide này sang slide khác</b>. <b>Animation</b> là hiệu ứng cho <b>chữ hoặc hình bên trong</b> một slide.',
 L:[
 ['Slide là gì?','<p>PowerPoint dùng để làm bài thuyết trình. Mỗi trang gọi là một <b>slide</b> (trang chiếu).</p><p>Slide đầu tiên là <b>slide tiêu đề</b>, ghi tên bài và tên người trình bày.</p>'],
 ['Thêm slide và chọn bố cục','<p>Bấm <b>New Slide</b> (hoặc <kbd>Ctrl</kbd>+<kbd>M</kbd>) để thêm slide mới.</p><p><b>Layout</b> (bố cục) quyết định chỗ đặt tiêu đề, chữ và hình trên slide.</p>'],
 ['Chèn hình ảnh','<p>Giống Word, em vào thẻ <b>Insert</b> để chèn <b>Pictures</b>, <b>Shapes</b>, <b>Table</b>. Hình ảnh giúp người xem hiểu nhanh hơn.</p>'],
 ['Hai loại hiệu ứng','<p><b>Transition</b>: cách slide này chuyển sang slide kế, ví dụ lật như trang sách.</p><p><b>Animation</b>: cách một dòng chữ hoặc bức ảnh xuất hiện trong slide, ví dụ bay vào từ bên trái.</p>'],
 ['Trình chiếu','<ul><li><kbd>F5</kbd> chiếu từ slide đầu tiên</li><li><kbd>Shift</kbd>+<kbd>F5</kbd> chiếu từ slide đang mở</li><li>Phím mũi tên, phím cách hoặc bấm chuột để sang slide kế</li><li><kbd>Esc</kbd> thoát trình chiếu</li></ul>'],
 ['Slide đẹp và dễ hiểu','<ul><li>Ít chữ, chữ to, dễ đọc từ cuối lớp.</li><li>Màu chữ nổi rõ trên màu nền.</li><li>Dùng hình minh hoạ rõ nét.</li><li>Nhìn người nghe và nói bằng lời của mình.</li></ul>']
 ]},
{id:'net',name:'Internet và tìm kiếm',sub:'Trình duyệt, địa chỉ web, tin cậy hay không',c:'#0a7fb8',icon:'<circle cx="12" cy="12" r="9"/><path d="M3 12h18M12 3c3 3 3 15 0 18M12 3c-3 3-3 15 0 18"/>',
 tip:'Trước khi tin một thông tin trên mạng, em hỏi ba câu: <b>Ai viết? Viết khi nào? Nơi khác có nói giống vậy không?</b>',
 L:[
 ['Internet và trang web','<p><b>Internet</b> là mạng nối hàng tỉ máy tính trên khắp thế giới. <b>Trang web</b> là nơi chứa thông tin trên Internet.</p><p><b>Wi-Fi</b> giúp máy kết nối mạng mà không cần dây.</p>'],
 ['Trình duyệt','<p>Trình duyệt là phần mềm để xem trang web: <b>Chrome, Edge, Firefox, Safari</b>.</p><ul><li><b>Back</b> quay lại trang trước, <b>Forward</b> đi tới</li><li><b>Refresh</b> (<kbd>F5</kbd>) tải lại trang</li><li><b>Tab</b> mở nhiều trang trong một cửa sổ</li><li><b>Bookmark</b> (Favorites) lưu trang em thích</li></ul>'],
 ['Địa chỉ web','<p>Mỗi trang web có một địa chỉ gọi là <b>URL</b>, ví dụ <i>https://www.moet.gov.vn</i>.</p><ul><li><b>https</b> và hình ổ khoá: kết nối được bảo mật.</li><li><b>.vn</b> Việt Nam, <b>.edu</b> giáo dục, <b>.gov</b> chính phủ, <b>.com</b> thương mại, <b>.org</b> tổ chức.</li></ul>'],
 ['Tìm kiếm giỏi','<p><b>Máy tìm kiếm</b> như Google, Bing, Cốc Cốc giúp em tìm thông tin.</p><p>Dùng <b>từ khoá</b> ngắn gọn, đúng ý. Đặt cụm từ trong <b>“ngoặc kép”</b> để tìm chính xác cụm đó.</p>'],
 ['Liên kết, tải xuống, tải lên','<p><b>Hyperlink</b> (siêu liên kết) là chữ hoặc hình bấm vào sẽ mở trang khác. Con trỏ chuột đổi thành hình bàn tay.</p><p><b>Download</b> là tải từ Internet về máy. <b>Upload</b> là đưa tệp từ máy lên Internet.</p>'],
 ['Thông tin có đáng tin không?','<ul><li>Ai viết? Có phải người hiểu biết về chủ đề này không?</li><li>Viết khi nào? Còn mới không?</li><li>Các trang khác có nói giống vậy không?</li></ul><p>Trang của trường học, cơ quan nhà nước, báo lớn thường đáng tin hơn.</p>']
 ]},
{id:'gt',name:'Thư điện tử và giao tiếp',sub:'Email, gọi video, làm việc nhóm',c:'#c2379a',icon:'<rect x="3" y="5" width="18" height="14" rx="2"/><path d="M3 7l9 6 9-6"/>',
 tip:'<b>Reply</b> trả lời cho người gửi. <b>Reply All</b> trả lời cho tất cả mọi người trong thư. <b>Forward</b> chuyển thư cho người khác.',
 L:[
 ['Địa chỉ email','<p>Địa chỉ email có dạng <b>tên@nhà-cung-cấp</b>, ví dụ <i>may.nguyen@gmail.com</i>.</p><p>Ký hiệu <b>@</b> đọc là “a còng”. Địa chỉ email không có dấu cách.</p>'],
 ['Các phần của một bức thư','<ul><li><b>To</b>: người nhận</li><li><b>Cc</b>: gửi thêm một bản cho người khác cùng biết</li><li><b>Bcc</b>: gửi một bản mà những người nhận khác không nhìn thấy</li><li><b>Subject</b>: tiêu đề thư</li><li><b>Attach</b> (hình kẹp giấy): đính kèm tệp</li></ul>'],
 ['Các hộp thư','<ul><li><b>Inbox</b>: thư đến</li><li><b>Sent</b>: thư đã gửi</li><li><b>Drafts</b>: thư nháp, viết chưa xong</li><li><b>Spam / Junk</b>: thư rác</li><li><b>Trash</b>: thư đã xoá</li></ul>'],
 ['Viết thư lịch sự','<ul><li>Có tiêu đề rõ ràng.</li><li>Mở đầu bằng lời chào, kết thúc bằng lời cảm ơn và tên em.</li><li>Không VIẾT HOA TOÀN BỘ vì giống như đang hét.</li><li>Đọc lại trước khi bấm <b>Send</b>.</li></ul>'],
 ['Nhiều cách liên lạc','<p>Email hợp với thư dài và gửi tệp. <b>Tin nhắn văn bản</b> (SMS) và <b>tin nhắn tức thời</b> (như Zalo, Messenger) hợp với trao đổi nhanh. <b>Gọi video</b> (Zoom, Google Meet, Teams) hợp với học và họp trực tuyến.</p>'],
 ['Cùng làm việc nhóm','<p>Với tài liệu trực tuyến như <b>Google Docs</b>, cả nhóm cùng sửa một bài cùng lúc. Lưu trữ đám mây như <b>Google Drive, OneDrive</b> giúp chia sẻ tệp.</p><p>Khi làm nhóm, em tôn trọng ý kiến của bạn và không xoá phần bài của bạn khi chưa hỏi.</p>']
 ]},
{id:'at',name:'An toàn và công dân số',sub:'Mật khẩu, lừa đảo, bản quyền, ứng xử',c:'#cf3f2e',icon:'<path d="M12 3l8 3v6c0 5-3.5 8-8 9-4.5-1-8-4-8-9V6z"/><path d="M9 12l2 2 4-4"/>',
 tip:'Gặp chuyện gì lạ hoặc làm em lo lắng trên mạng, đáp án đúng gần như luôn là: <b>không làm theo và báo cho bố mẹ, thầy cô</b>.',
 L:[
 ['Thông tin cá nhân','<p>Họ tên đầy đủ, địa chỉ nhà, số điện thoại, tên trường lớp, mật khẩu và ảnh của em là <b>thông tin cá nhân</b>.</p><p>Không chia sẻ những thứ này với người lạ trên mạng.</p>'],
 ['Mật khẩu mạnh','<ul><li>Dài từ 8 ký tự trở lên.</li><li>Có chữ hoa, chữ thường, số và ký hiệu.</li><li>Không dùng tên, ngày sinh hay 123456.</li><li>Chỉ em và bố mẹ biết. Dùng máy chung xong thì <b>đăng xuất</b> (Sign out).</li></ul>'],
 ['Virus và lừa đảo','<p><b>Virus</b> là phần mềm xấu làm hỏng máy hoặc lấy trộm thông tin. <b>Phần mềm diệt virus</b> giúp tìm và loại bỏ chúng.</p><p><b>Lừa đảo</b> thường là thư hay tin nhắn báo “trúng thưởng”, giục làm gấp, xin mật khẩu. Em không bấm vào đường link lạ, không mở tệp đính kèm từ người lạ.</p>'],
 ['Bắt nạt trên mạng','<p>Nếu bị trêu chọc, xúc phạm trên mạng: <b>không đáp trả</b>, <b>chụp màn hình</b> để lưu bằng chứng, <b>chặn</b> người đó và <b>báo người lớn</b>.</p><p>Em cũng chỉ viết những lời mà em dám nói trực tiếp với bạn.</p>'],
 ['Bản quyền','<p>Bài viết, ảnh, nhạc, phần mềm đều có chủ. Khi dùng, em <b>xin phép</b> hoặc <b>ghi rõ nguồn</b>.</p><p>Chép bài của người khác rồi nói là của mình gọi là <b>đạo văn</b>. Dùng phần mềm sao chép lậu là vi phạm bản quyền.</p>'],
 ['Dấu chân số và sức khoẻ','<p>Mọi thứ em đăng lên mạng để lại <b>dấu chân số</b> và có thể tồn tại rất lâu. Hãy nghĩ kỹ trước khi đăng.</p><p>Ngồi thẳng lưng, mắt cách màn hình khoảng 50 đến 70 cm. Cứ khoảng 20 phút cho mắt nghỉ, nhìn ra xa một lúc.</p>']
 ]}
];

