addL('mt',['Thiết bị di động','<p><b>Điện thoại thông minh</b> và <b>máy tính bảng</b> là thiết bị di động: nhỏ gọn, chạy bằng pin, điều khiển bằng màn hình cảm ứng.</p><p>Chúng cũng có hệ điều hành (Android, iOS) và cài thêm được <b>ứng dụng</b> (app). Chúng vào Internet bằng Wi-Fi hoặc mạng di động 4G, 5G.</p><p>Dùng an toàn: đặt mã khoá màn hình và hỏi ba mẹ trước khi cài ứng dụng mới.</p>']);
addL('net',['Mạng, website và trang web','<p><b>Mạng máy tính</b> là từ hai máy trở lên nối với nhau để chia sẻ thông tin. Internet là mạng lớn nhất thế giới.</p><p>Máy kết nối mạng bằng <b>dây cáp</b>, bằng <b>Wi-Fi</b> hoặc bằng <b>mạng di động</b>.</p><p>Một <b>website</b> gồm nhiều <b>trang web</b> (webpage) liên quan với nhau. Trang đầu tiên gọi là <b>trang chủ</b> (home page).</p>']);
addL('vb',['Các phím đặc biệt','<ul><li><kbd>Shift</kbd>: giữ cùng một chữ cái để gõ chữ in hoa, giữ cùng phím số để gõ ký hiệu phía trên.</li><li><kbd>Tab</kbd>: thụt đầu dòng hoặc nhảy sang ô kế tiếp.</li><li><kbd>Esc</kbd>: thoát hoặc huỷ việc đang làm.</li><li><kbd>Ctrl</kbd> và <kbd>Alt</kbd>: bấm cùng phím khác để tạo phím tắt.</li><li>Các phím mũi tên: di chuyển con trỏ. <kbd>Home</kbd> về đầu dòng, <kbd>End</kbd> về cuối dòng.</li></ul>']);
addL('at',['Công dân số là gì?','<p><b>Công dân số</b> là người dùng Internet và thiết bị số một cách có trách nhiệm.</p><ul><li><b>Quyền</b>: được học tập, tìm thông tin, được giữ riêng tư và được an toàn trên mạng.</li><li><b>Trách nhiệm</b>: tôn trọng người khác, tôn trọng bản quyền, không đăng tin sai.</li></ul><p>Internet là nơi <b>công cộng</b> và <b>lâu dài</b>: nhiều người xem được thứ em đăng, và nó có thể còn đó rất lâu.</p>']);
const yn=(t,q,items,e)=>Q.push({t,k:'sort',yn:1,q,g:['Đúng','Sai'],items:items.map(x=>[x[0],x[1]?0:1]),e});
