one('mt','Máy tính bảng thường được điều khiển bằng cách nào?',['Chạm vào màn hình cảm ứng','Chỉ dùng chuột có dây','Chỉ dùng bàn phím rời','Dùng điều khiển ti vi'],'Máy tính bảng dùng màn hình cảm ứng: em chạm, vuốt để ra lệnh.');
one('net','Mạng máy tính là gì?',['Nhiều máy tính nối với nhau để chia sẻ thông tin','Một loại phần mềm vẽ','Một chiếc máy tính rất to','Một loại bàn phím'],'Mạng là các máy nối với nhau. Internet là mạng lớn nhất.');
one('net','Website khác trang web (webpage) ở điểm nào?',['Website gồm nhiều trang web liên quan với nhau','Website chỉ có đúng một trang','Trang web lớn hơn website','Hai thứ không liên quan gì'],'Website giống một cuốn sách, mỗi trang web là một trang trong sách.');
one('vb','Giữ phím nào cùng một chữ cái để gõ chữ in hoa?',['Shift','Tab','Esc','Alt'],'Giữ Shift rồi gõ chữ cái sẽ được chữ in hoa.');
one('at','Công dân số là ai?',['Người dùng Internet có trách nhiệm, an toàn và tôn trọng người khác','Người có nhiều máy tính nhất','Người chơi trò chơi giỏi nhất','Người không bao giờ dùng Internet'],'Công dân số tốt biết quyền và trách nhiệm của mình khi lên mạng.');
yn('mt','Chọn Đúng hoặc Sai cho mỗi câu về bộ nhớ.',[['RAM mất dữ liệu khi tắt máy',1],['USB lưu được dữ liệu lâu dài',1],['Màn hình là thiết bị lưu trữ',0]],'RAM là trí nhớ tạm, USB lưu lâu dài, màn hình là thiết bị ra.');
yn('hdh','Chọn Đúng hoặc Sai cho mỗi câu.',[['Điện thoại thông minh cũng có hệ điều hành',1],['Tệp đã vào Thùng rác thì không lấy lại được',0],['Một thư mục có thể chứa thư mục khác',1]],'Điện thoại dùng Android hoặc iOS. Tệp trong Thùng rác khôi phục được bằng Restore.');
yn('pm','Chọn Đúng hoặc Sai cho mỗi câu.',[['Save As tạo ra một tệp mới',1],['Ctrl + Z dùng để in',0],['Nên cài phần mềm từ nguồn tin cậy',1]],'Ctrl + Z là hoàn tác. Phím tắt để in là Ctrl + P.');
yn('vb','Chọn Đúng hoặc Sai cho mỗi câu về các phím.',[['Phím Enter dùng để xuống dòng',1],['Phím Caps Lock dùng để xoá chữ',0],['Giữ Shift cùng một chữ cái sẽ được chữ in hoa',1]],'Caps Lock bật hoặc tắt chữ in hoa. Xoá chữ là Backspace và Delete.');
yn('bt','Chọn Đúng hoặc Sai cho mỗi câu về bảng tính.',[['Công thức bắt đầu bằng dấu =',1],['Hàng được đặt tên bằng chữ cái',0],['Hàm MIN tìm số nhỏ nhất',1]],'Hàng đặt tên bằng số, cột đặt tên bằng chữ cái.');
yn('tc','Chọn Đúng hoặc Sai cho mỗi câu về trình chiếu.',[['Phím Esc thoát khỏi trình chiếu',1],['Slide càng nhiều chữ càng dễ xem',0],['Transition là hiệu ứng giữa hai slide',1]],'Slide tốt có ít chữ và chữ to.');
yn('net','Chọn Đúng hoặc Sai cho mỗi câu.',[['Wi-Fi kết nối mạng không cần dây',1],['Mọi thông tin trên Internet đều đúng',0],['Máy tính bảng có thể vào Internet',1]],'Trên mạng có cả tin đúng và tin sai, nên em cần kiểm tra nguồn.');
yn('gt','Chọn Đúng hoặc Sai cho mỗi câu.',[['Tin nhắn tức thời hợp với trao đổi nhanh',1],['Email không gửi kèm được tệp',0],['Khi làm nhóm nên hỏi bạn trước khi sửa phần của bạn',1]],'Email gửi kèm tệp được bằng nút hình kẹp giấy.');
yn('at','Chọn Đúng hoặc Sai cho mỗi câu.',[['Thứ đã đăng lên mạng có thể tồn tại rất lâu',1],['Nên dùng chung một mật khẩu với bạn thân',0],['Bị bắt nạt trên mạng thì nên báo người lớn',1]],'Mật khẩu chỉ em và ba mẹ biết, không chia sẻ với bạn.');
typ('pm','Gõ tổ hợp phím dùng để lưu bài. Viết theo mẫu: Ctrl+A',['Ctrl+S'],'Ctrl + S là Save, lưu bài.');
typ('bt','Gõ địa chỉ của ô nằm ở cột D, hàng 2.',['D2'],'Cột trước, hàng sau: D2.');
