/* ==== Đợt bổ sung theo đề cương 7 chuyên đề IC3 GS6 Spark: tách Cộng tác và Công dân số, hoàn thiện Bảng tính, lấp các mục còn thiếu ==== */
{const tp_=id=>TOPICS.find(x=>x.id===id),AT=tp_('at'),GT=tp_('gt');
 GT.name='Thư điện tử và truyền thông';GT.sub='Email, tin nhắn, gọi video, đăng bài';
 AT.name='An toàn và bảo mật';AT.sub='Mật khẩu, virus, lừa đảo, sức khoẻ';
 AT.tip='Gặp chuyện gì lạ hoặc làm em lo lắng trên mạng, đáp án đúng gần như luôn là: <b>không làm theo và báo cho bố mẹ, thầy cô</b>.';
 AT.L.splice(6,1);AT.L.splice(4,1);
 AT.L[4]=['Sức khoẻ khi dùng máy tính','<p><b>Cơ thể</b>: ngồi thẳng lưng, mắt cách màn hình khoảng 50 đến 70 cm. Cứ khoảng 20 phút cho mắt nghỉ bằng cách nhìn ra xa. Đứng dậy vận động sau mỗi buổi học.</p><p><b>Tinh thần</b>: dùng máy có giờ giấc, không dùng ngay trước khi ngủ. Nếu chuyện trên mạng làm em buồn, lo hoặc sợ, hãy nói với ba mẹ hoặc thầy cô.</p>'];
 TOPICS.splice(TOPICS.indexOf(GT)+1,0,{id:'ct',name:'Cộng tác',sub:'Làm việc nhóm, chia sẻ tài liệu, họp trực tuyến',c:'#a87400',icon:'<circle cx="8" cy="8" r="3"/><circle cx="16" cy="8" r="3"/><path d="M2 20c0-3.300 2.700-6 6-6s6 2.700 6 6M10 20c0-3.300 2.700-6 6-6s6 2.700 6 6"/>',
  tip:'Câu hỏi về làm việc nhóm thường có đáp án đúng là cách làm <b>lịch sự và hỏi ý bạn trước</b>: nhận xét thay vì xoá, giơ tay thay vì nói chen.',L:[
  ['Cộng tác là gì?','<p><b>Cộng tác</b> là cùng nhau làm một việc. Nhờ Internet, các bạn không cần ngồi cạnh nhau vẫn làm chung được một bài.</p><ul><li>Có nhiều ý tưởng hơn.</li><li>Làm nhanh hơn vì mỗi bạn một phần.</li><li>Học được cách làm hay của nhau.</li></ul>'],
  ['Công cụ cộng tác và quyền chia sẻ','<ul><li><b>Tài liệu trực tuyến</b> (Google Docs, Word trên web): cả nhóm cùng sửa một bài.</li><li><b>Lưu trữ đám mây</b> (Google Drive, OneDrive): để tệp ở một nơi chung.</li><li><b>Gọi video</b> (Google Meet, Zoom, Teams): họp và học trực tuyến.</li></ul><p>Khi bấm <b>Share</b> (Chia sẻ), em chọn quyền cho bạn: <b>Xem</b>, <b>Nhận xét</b> hoặc <b>Chỉnh sửa</b>.</p>'],
  ['Cùng lúc và không cùng lúc','<p><b>Cùng lúc</b>: mọi người có mặt cùng một thời điểm, như gọi video hay trò chuyện trực tiếp. Hợp khi cần bàn nhanh.</p><p><b>Không cùng lúc</b>: mỗi người làm vào lúc mình rảnh, như email hay nhận xét để lại trong tài liệu. Hợp khi các bạn bận khác giờ nhau.</p>'],
  ['Lịch sự khi viết chung','<ul><li>Không xoá hay sửa phần của bạn khi chưa hỏi.</li><li>Muốn góp ý thì để lại <b>nhận xét</b> (Comment) thay vì sửa thẳng.</li><li>Viết rõ ràng, lịch sự, không viết hoa toàn bộ.</li><li>Làm xong phần của mình đúng hạn.</li></ul>'],
  ['Lịch sự khi gọi video','<ul><li>Vào đúng giờ, ngồi nơi yên tĩnh, gọn gàng.</li><li><b>Tắt micro</b> khi không nói.</li><li>Muốn phát biểu thì bấm <b>giơ tay</b> và chờ được mời.</li><li>Nhìn vào màn hình, không làm việc riêng.</li><li>Không chụp hay ghi hình buổi họp khi chưa xin phép.</li></ul>'],
  ['Góp ý cho bạn','<p>Khi <b>góp ý</b>: khen điều tốt trước, nói cụ thể chỗ nào nên sửa, đề xuất cách sửa. Nói về bài làm, không chê người làm.</p><p>Khi <b>nhận góp ý</b>: lắng nghe, cảm ơn bạn, rồi xem sửa được gì. Góp ý giúp bài của cả nhóm tốt hơn.</p>']]});
 TOPICS.splice(TOPICS.indexOf(AT),0,{id:'cd',name:'Công dân số',sub:'Quyền, trách nhiệm, danh tính và ứng xử trên mạng',c:'#4f46a5',icon:'<rect x="3" y="5" width="18" height="14" rx="2"/><circle cx="9" cy="11" r="2.200"/><path d="M5.500 16c.800-1.800 2-2.500 3.500-2.500s2.700.700 3.500 2.500M15 10h4M15 14h3"/>',
  tip:'Trước khi đăng hay gửi bất cứ điều gì, em tự hỏi: <b>Có đúng không? Có tử tế không? Có cần thiết không?</b>',L:[
  ['Công dân số là gì?','<p><b>Công dân số</b> là người dùng Internet và thiết bị số một cách có trách nhiệm, an toàn và tôn trọng người khác.</p><p>Giống như ở trường có nội quy, trên mạng cũng có những điều nên làm và không nên làm.</p>'],
  ['Quyền và trách nhiệm','<p><b>Quyền</b> của em trên mạng:</p><ul><li>Được học tập và tìm thông tin.</li><li>Được giữ kín thông tin riêng.</li><li>Được an toàn và được tôn trọng.</li></ul><p><b>Trách nhiệm</b> của em:</p><ul><li>Tôn trọng người khác.</li><li>Tôn trọng bản quyền, ghi nguồn khi dùng bài của người khác.</li><li>Không đăng hay chia sẻ tin sai.</li></ul>'],
  ['Danh tính số và thông tin cá nhân','<p><b>Danh tính số</b> là hình ảnh của em trên mạng: tên tài khoản, ảnh đại diện, những gì em đăng.</p><p><b>Thông tin nhận dạng cá nhân</b> gồm họ tên đầy đủ, ngày sinh, địa chỉ nhà, trường lớp, số điện thoại, ảnh. Em giữ kín những thứ này.</p><p>Đặt tên tài khoản bằng biệt danh, không dùng họ tên thật kèm trường lớp. Hỏi ba mẹ trước khi tạo tài khoản mới.</p>'],
  ['Internet là nơi công cộng và lâu dài','<p><b>Công cộng</b>: thứ em đăng có thể được rất nhiều người xem, kể cả người em không quen.</p><p><b>Lâu dài</b>: người khác có thể lưu hoặc chia sẻ lại, nên xoá rồi vẫn có thể còn. Những gì em để lại tạo thành <b>dấu chân số</b>.</p><p>Trước khi đăng ảnh có mặt bạn, em hỏi xem bạn có đồng ý không.</p>'],
  ['Ứng xử lịch sự trên mạng','<ul><li>Dùng lời lẽ tử tế, như khi nói trực tiếp.</li><li>Không VIẾT HOA TOÀN BỘ, không gửi tin lặp đi lặp lại.</li><li>Tôn trọng ý kiến khác mình.</li><li>Dùng lời nói khiến bạn nào cũng thấy được chào đón, không chê bai ai vì khác biệt.</li></ul>'],
  ['Khi gặp điều tiêu cực','<ul><li>Lời lẽ khó nghe: <b>không đáp trả</b>. Cãi nhau thường làm mọi chuyện tệ hơn.</li><li><b>Chặn</b> (Block) và <b>báo cáo</b> (Report) người đó.</li><li>Chụp màn hình để lưu bằng chứng và nói với người lớn.</li><li>Nội dung làm em sợ: tắt đi và nói với ba mẹ hoặc thầy cô.</li><li>Tin chưa rõ thật giả: kiểm tra ở nguồn đáng tin, chưa chắc thì không chia sẻ.</li></ul>'],
  ['Bản quyền và dùng đúng luật','<p>Bài viết, ảnh, nhạc, phần mềm đều có tác giả. Khi dùng, em <b>xin phép</b> hoặc <b>ghi rõ nguồn</b>.</p><p>Chép bài của người khác rồi nói là của mình gọi là <b>đạo văn</b>. Dùng phần mềm sao chép lậu là vi phạm bản quyền.</p><p>Một số tác phẩm thuộc <b>phạm vi công cộng</b>, mọi người được dùng tự do. Một số khác có giấy phép <b>Creative Commons</b>: được dùng nếu làm theo điều kiện của tác giả, thường là ghi tên tác giả.</p>']]});
 addL('at',['Khoá thiết bị và đổi mật khẩu','<p><b>Khoá màn hình</b> mỗi khi rời máy, kể cả một lát. Trên Windows nhấn phím <kbd>Windows</kbd>+<kbd>L</kbd>. Điện thoại và máy tính bảng nên đặt mã khoá.</p><p><b>Đổi mật khẩu ngay</b> khi em nghi có người khác biết, hoặc khi trang web báo tài khoản có vấn đề. Quên mật khẩu thì dùng “Quên mật khẩu” cùng ba mẹ để đặt lại.</p>']);
 addL('at',['Dấu vết khi duyệt web','<p>Trình duyệt ghi lại <b>lịch sử</b> các trang em đã xem. Trang web lưu <b>cookie</b>, là tệp nhỏ để ghi nhớ em, ví dụ để em không phải đăng nhập lại.</p><p>Trên máy dùng chung: không bấm “Lưu mật khẩu”, đăng xuất khi xong. <b>Chế độ riêng tư</b> (ẩn danh) giúp trình duyệt không lưu lịch sử trên máy đó, nhưng không làm em vô hình trên mạng.</p>']);
 addL('mt',['Thiết bị ngoại vi và cổng kết nối','<p><b>Thiết bị ngoại vi</b> là thiết bị cắm thêm vào máy tính: chuột, bàn phím rời, máy in, loa, webcam. Bộ phận có sẵn trong máy như màn hình cảm ứng của máy tính bảng gọi là thiết bị <b>tích hợp</b>.</p><ul><li><b>Cổng USB</b>: cắm chuột, bàn phím, USB, máy in.</li><li><b>Cổng HDMI</b>: truyền hình ảnh và âm thanh sang màn hình, ti vi, máy chiếu.</li><li><b>Giắc âm thanh</b>: cắm tai nghe, loa.</li><li><b>Bluetooth</b>: kết nối không dây với thiết bị ở gần.</li></ul>']);
 addL('hdh',['Tài khoản và cài đặt','<p>Để dùng máy tính, em <b>đăng nhập</b> bằng tên tài khoản và mật khẩu. Mỗi người một tài khoản thì tệp và cài đặt của ai người nấy giữ.</p><p>Trong <b>Settings</b> (Cài đặt) em đổi được hình nền, âm lượng, ngày giờ, cỡ chữ. Những cài đặt quan trọng như cài phần mềm hay mạng thì để người lớn làm.</p>']);
 addL('pm',['Ứng dụng trên máy, trên web và trên điện thoại','<ul><li><b>Ứng dụng trên máy tính</b>: phải cài vào máy, ví dụ Word, Paint.</li><li><b>Ứng dụng web</b>: chạy ngay trong trình duyệt, không cần cài, ví dụ Google Docs, Gmail. Cần có mạng.</li><li><b>Ứng dụng di động</b> (app): cài trên điện thoại, máy tính bảng.</li></ul><p>Có phần mềm phải trả tiền, có phần mềm miễn phí. Dù loại nào cũng chỉ tải từ nơi tin cậy và hỏi ba mẹ trước.</p>']);
 addL('vb',['Sao lưu và các lựa chọn khi in','<p><b>Sao lưu</b> (backup) là lưu thêm một bản của tệp ở nơi khác, như USB hoặc lưu trữ đám mây, để phòng khi máy hỏng hay lỡ xoá.</p><p>Trong hộp thoại in em chọn được: <b>máy in</b> nào, <b>Copies</b> (số bản), <b>Pages</b> (in trang nào), in <b>một mặt hay hai mặt</b>, và <b>hướng giấy</b>. In hai mặt giúp tiết kiệm giấy.</p>']);
 addL('net',['Tìm thông tin trong một trang web','<p>Một trang web có nhiều loại thông tin: chữ, hình ảnh, video, liên kết và cả <b>quảng cáo</b>. Quảng cáo thường có chữ “Quảng cáo” hoặc “Được tài trợ”.</p><p>Nhấn <kbd>Ctrl</kbd>+<kbd>F</kbd> rồi gõ một từ để tìm nhanh từ đó trong trang.</p><p>Trong trang kết quả tìm kiếm, em đọc <b>tiêu đề</b> và <b>dòng mô tả</b> để chọn kết quả đúng thứ mình cần, và ghi lại địa chỉ trang đã dùng.</p>']);
 addL('net',['Mạng có đang kết nối không?','<p>Nhìn biểu tượng <b>Wi-Fi</b> hoặc mạng ở góc màn hình để biết máy đã kết nối chưa.</p><p>Khi không vào được mạng, em thử lần lượt: xem Wi-Fi đã bật chưa, có đang ở chế độ máy bay không, tắt rồi bật lại Wi-Fi, khởi động lại máy. Vẫn không được thì nhờ người lớn kiểm tra bộ phát Wi-Fi.</p>']);
 addL('gt',['Đăng bài và chia sẻ đúng chỗ','<p>Trước khi đăng, em chọn <b>nơi phù hợp</b>: việc của lớp thì đăng trong nhóm lớp, không đăng ở nơi công khai.</p><ul><li>Mỗi nhóm, mỗi trang có <b>nội quy</b> riêng. Đọc trước khi đăng.</li><li>Dùng lời lẽ khiến bạn nào cũng thấy được tôn trọng.</li><li>Hỏi người lớn khi chưa chắc có nên đăng không.</li></ul>']);
 addL('bt',['Làm quen cửa sổ Excel','<p>Một tệp Excel gọi là <b>workbook</b> (sổ tính), đuôi <b>.xlsx</b>. Trong đó có một hay nhiều <b>trang tính</b> (sheet), đổi qua lại bằng các thẻ ở phía dưới.</p><ul><li><b>Name Box</b> (hộp tên): hiện địa chỉ ô đang chọn.</li><li><b>Formula Bar</b> (thanh công thức): hiện nội dung hoặc công thức thật của ô.</li></ul>']);
 addL('bt',['Chọn và định dạng ô','<ul><li>Kéo chuột để chọn một <b>vùng</b> ô. Bấm vào chữ cái cột hoặc số hàng để chọn cả cột, cả hàng.</li><li>Dùng <b>B</b>, màu chữ, <b>màu nền</b> và <b>đường viền</b> (Borders) cho bảng dễ nhìn.</li><li><b>Merge &amp; Center</b>: gộp nhiều ô thành một và căn giữa, hay dùng cho tiêu đề bảng.</li><li>Số hiện thành <b>####</b> nghĩa là cột quá hẹp. Kéo cho cột rộng ra.</li></ul>']);
 addL('bt',['Tự điền và sao chép công thức','<p>Ô vuông nhỏ ở góc dưới bên phải ô đang chọn gọi là <b>nút điền</b> (fill handle). Kéo nó để Excel điền tiếp giúp em.</p><ul><li>Gõ 1 và 2, chọn cả hai rồi kéo: được 3, 4, 5.</li><li>Gõ Thứ Hai rồi kéo: được Thứ Ba, Thứ Tư.</li><li>Kéo một ô có công thức: công thức được chép xuống và tự đổi địa chỉ ô cho đúng hàng.</li></ul>']);
 addL('bt',['Hàng, cột, trang tính và in','<ul><li>Bấm chuột phải vào số hàng hoặc chữ cột, chọn <b>Insert</b> để thêm, <b>Delete</b> để xoá.</li><li>Bấm đúp vào thẻ trang tính để <b>đổi tên</b>, bấm dấu <b>+</b> để thêm trang tính mới.</li><li>Lưu bằng <kbd>Ctrl</kbd>+<kbd>S</kbd>. In bằng <kbd>Ctrl</kbd>+<kbd>P</kbd> và xem trước để bảng không bị cắt.</li></ul>']);
 const mv=(s,id)=>{const q=Q.find(x=>x.q.indexOf(s)===0);if(q)q.t=id};
 ['Chép nguyên bài viết','Em dùng một bức ảnh trên mạng','“Dấu chân số” là gì?','Dùng phần mềm sao chép lậu','Công dân số là ai?'].forEach(s=>mv(s,'cd'));mv('Bốn bạn trong nhóm muốn cùng sửa','ct');
}
